-- Proposta inicial para PostgreSQL/Supabase. Revisar antes de aplicar em produção.
create extension if not exists pgcrypto;
create type public.editorial_status as enum ('draft','pending_review','published','withdrawn');
create type public.availability_status as enum ('available','out_of_print','unknown','not_for_sale');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, role text not null default 'reader' check(role in ('reader','editor','admin')), created_at timestamptz not null default now());
create table public.publishers (id uuid primary key default gen_random_uuid(), name text not null, region text, website text, created_at timestamptz not null default now());
create table public.authors (id uuid primary key default gen_random_uuid(), full_name text not null, bio text, official_url text, image_url text, image_license text, created_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null, region text, official_label text, parent_id uuid references public.categories(id), unique(name,region));
create table public.books (id uuid primary key default gen_random_uuid(), title text not null, original_title text, subtitle text, description text, language text, region text not null, publisher_id uuid references public.publishers(id), category_id uuid references public.categories(id), audience text, keywords text[] not null default '{}', availability public.availability_status not null default 'unknown', editorial_status public.editorial_status not null default 'draft', completeness smallint not null default 0 check(completeness between 0 and 100), last_verified_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index books_region_status_idx on public.books(region, editorial_status);
create index books_title_search_idx on public.books using gin(to_tsvector('simple', coalesce(title,'') || ' ' || coalesce(subtitle,'') || ' ' || coalesce(description,'')));
create table public.book_authors (book_id uuid references public.books(id) on delete cascade, author_id uuid references public.authors(id), contribution text not null default 'author', position int not null default 0, primary key(book_id,author_id,contribution));
create table public.book_editions (id uuid primary key default gen_random_uuid(), book_id uuid not null references public.books(id) on delete cascade, isbn text, edition_label text, format text, pages int, dimensions text, publication_year int, first_publication_year int, language text, region text not null, unique(isbn,region));
create table public.book_images (id uuid primary key default gen_random_uuid(), book_id uuid not null references public.books(id) on delete cascade, edition_id uuid references public.book_editions(id), url text not null, source_url text, license text, verified_at timestamptz, alt_text text);
create table public.book_sources (id uuid primary key default gen_random_uuid(), book_id uuid not null references public.books(id) on delete cascade, url text not null, source_name text, accessed_at timestamptz not null default now(), fields text[] not null default '{}', notes text);
create table public.evidence_reviews (id uuid primary key default gen_random_uuid(), book_id uuid not null references public.books(id) on delete cascade, claim text not null, review_type text not null check(review_type in ('editorial','content','external_evidence','practicality','bibliographic','limitation')), method text, findings text, limitations text, sources jsonb not null default '[]', reviewer_id uuid references public.profiles(id), reviewed_at timestamptz);
create table public.favorites (user_id uuid references public.profiles(id) on delete cascade, book_id uuid references public.books(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,book_id));
create table public.reading_lists (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, name text not null, is_private boolean not null default true, created_at timestamptz not null default now());
create table public.reading_list_items (list_id uuid references public.reading_lists(id) on delete cascade, book_id uuid references public.books(id) on delete cascade, position int not null default 0, note text, primary key(list_id,book_id));
create table public.audit_logs (id bigint generated always as identity primary key, actor_id uuid references public.profiles(id), entity text not null, entity_id uuid, action text not null, changes jsonb, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.books enable row level security; alter table public.favorites enable row level security; alter table public.reading_lists enable row level security; alter table public.reading_list_items enable row level security;
create policy profile_self on public.profiles for select using (id=auth.uid());
create policy published_books_read on public.books for select using (editorial_status='published');
create policy favorites_self on public.favorites for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy lists_self on public.reading_lists for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy list_items_self on public.reading_list_items for all using (exists(select 1 from public.reading_lists l where l.id=list_id and l.user_id=auth.uid())) with check (exists(select 1 from public.reading_lists l where l.id=list_id and l.user_id=auth.uid()));
-- Políticas de escrita de editor/admin devem ser adicionadas usando função de autorização segura e validada; não confiar em role fornecida pelo cliente.
